    for (int i = 1; i <= 20; ++i) {
        ApproximateHistogram hLow = new ApproximateHistogram(5);
        ApproximateHistogram hHigh = new ApproximateHistogram(5);
        hLow.offer(lowerLimit - i);
        hHigh.offer(upperLimit + i);
        h.foldFast(hLow);
        h.foldFast(hHigh);
    }
