@Test
public void testRealtimeIndexTask() throws Exception {
    LOG.info("Starting test: ITRealtimeIndexTaskTest");
    try {
        // the task will run for 3 minutes and then shutdown itself
        String task = setShutOffTime(getTaskAsString(REALTIME_TASK_RESOURCE), new DateTime(System.currentTimeMillis() + TimeUnit.MINUTES.toMillis(3)));
        LOG.info("indexerSpec: [%s]\n", task);
        taskID = indexer.submitTask(task);
        // this posts 22 events, one every 4 seconds
        // each event contains the current time as its timestamp except
        //   the timestamp for the 14th event is early enough that the event should be ignored
        //   the timestamp for the 18th event is 2 seconds earlier than the 17th
        postEvents();
        // sleep for a while to let the events be ingested
        TimeUnit.SECONDS.sleep(5);
        // put the timestamps into the query structure
        String query_response_template = null;
        InputStream is = ITRealtimeIndexTaskTest.class.getResourceAsStream(REALTIME_QUERIES_RESOURCE);
        if (null == is) {
            throw new ISE("could not open query file: %s", REALTIME_QUERIES_RESOURCE);
        }
        query_response_template = IOUtils.toString(is, "UTF-8");
        String queryStr = query_response_template.replace("%%TIMEBOUNDARY_RESPONSE_TIMESTAMP%%", TIMESTAMP_FMT.print(dtFirst)).replace("%%TIMEBOUNDARY_RESPONSE_MAXTIME%%", TIMESTAMP_FMT.print(dtLast)).replace("%%TIMEBOUNDARY_RESPONSE_MINTIME%%", TIMESTAMP_FMT.print(dtFirst)).replace("%%TIMESERIES_QUERY_START%%", INTERVAL_FMT.print(dtFirst)).replace("%%TIMESERIES_QUERY_END%%", INTERVAL_FMT.print(dtLast.plusMinutes(2))).replace("%%TIMESERIES_RESPONSE_TIMESTAMP%%", TIMESTAMP_FMT.print(dtFirst)).replace("%%POST_AG_REQUEST_START%%", INTERVAL_FMT.print(dtFirst)).replace("%%POST_AG_REQUEST_END%%", INTERVAL_FMT.print(dtLast.plusMinutes(2))).replace("%%POST_AG_RESPONSE_TIMESTAMP%%", TIMESTAMP_FMT.print(dtGroupBy.withSecondOfMinute(0)));
        // should hit the queries all on realtime task or some on realtime task
        // and some on historical.  Which it is depends on where in the minute we were
        // when we started posting events.
        try {
            this.queryHelper.testQueriesFromString(getRouterURL(), queryStr, 2);
        } catch (Exception e) {
            throw Throwables.propagate(e);
        }
        // wait for the task to complete
        indexer.waitUntilTaskCompletes(taskID);
        // task should complete only after the segments are loaded by historical node
        RetryUtil.retryUntil(new Callable<Boolean>() {

            @Override
            public Boolean call() throws Exception {
                return coordinator.areSegmentsLoaded(INDEX_DATASOURCE);
            }
        }, true, 60000, 10, "Real-time generated segments loaded");
        // queries should be answered by historical
        this.queryHelper.testQueriesFromString(getRouterURL(), queryStr, 2);
    } catch (Exception e) {
        throw Throwables.propagate(e);
    } finally {
        unloadAndKillData(INDEX_DATASOURCE);
    }
}

@Test
public void testUnionQuery() throws Exception {
    final int numTasks = 4;
    try {
        // Load 4 datasources with same dimensions
        String task = setShutOffTime(getTaskAsString(UNION_TASK_RESOURCE), new DateTime(System.currentTimeMillis() + TimeUnit.MINUTES.toMillis(3)));
        List<String> taskIDs = Lists.newArrayList();
        for (int i = 0; i < numTasks; i++) {
            taskIDs.add(indexer.submitTask(withServiceName(withDataSource(task, UNION_DATASOURCE + i), EVENT_RECEIVER_SERVICE_PREFIX + i)));
        }
        for (int i = 0; i < numTasks; i++) {
            postEvents(i);
        }
        // sleep for a while to let the events ingested
        TimeUnit.SECONDS.sleep(5);
        // should hit the queries on realtime task
        LOG.info("Running Union Queries..");
        this.queryHelper.testQueriesFromFile(UNION_QUERIES_RESOURCE, 2);
        // wait for the task to complete
        for (int i = 0; i < numTasks; i++) {
            indexer.waitUntilTaskCompletes(taskIDs.get(i));
        }
        // task should complete only after the segments are loaded by historical node
        for (int i = 0; i < numTasks; i++) {
            final int taskNum = i;
            RetryUtil.retryUntil(new Callable<Boolean>() {

                @Override
                public Boolean call() throws Exception {
                    return coordinator.areSegmentsLoaded(UNION_DATASOURCE + taskNum);
                }
            }, true, 60000, 10, "Real-time generated segments loaded");
        }
        // run queries on historical nodes
        this.queryHelper.testQueriesFromFile(UNION_QUERIES_RESOURCE, 2);
    } catch (Exception e) {
        e.printStackTrace();
        throw Throwables.propagate(e);
    } finally {
        for (int i = 0; i < numTasks; i++) {
            unloadAndKillData(UNION_DATASOURCE + i);
        }
    }
}

